export const reactLessons = [
  {id:'react-001',level:'L1',title:'What is React and why is it used?',subtopic:'Foundations',what:'React is a JavaScript library for building user interfaces from reusable components. It lets you describe what the UI should look like for a given state and updates the DOM efficiently when state changes.',how:'A React application is a tree of components. State and props flow through that tree, React renders elements from the current state, and React commits the necessary DOM updates.',code:`function Welcome({ name }) {\n  return <h2>Hello, {name}</h2>;\n}` ,delivery:'React is a component-based UI library. I use it to split a frontend into reusable components, manage UI state, and render predictable views from state and props.',followups:['React vs Angular?','What is a component?','Why is React called declarative?'],traps:['Do not say React is a complete framework.','Do not describe the Virtual DOM as a literal second browser DOM.']},
  {id:'react-002',level:'L1',title:'JSX: what it is and how it works',subtopic:'Foundations',what:'JSX is syntax that lets you write HTML-like UI expressions inside JavaScript. It is transformed into JavaScript calls that create React elements.',how:'Expressions use braces, attributes use JavaScript-style values, and components must return a valid element tree. Modern React tooling transforms JSX during the build.',code:`const user = { name: 'Barani' };\n\nfunction Profile() {\n  return <h2 className="title">{user.name}</h2>;\n}` ,delivery:'JSX is not HTML. It is a syntax extension for JavaScript that makes component UI readable and is compiled into React element creation code.',followups:['Why className instead of class?','Can JSX return multiple elements?','Can we use JavaScript expressions in JSX?'],traps:['JSX expressions use braces; statements such as if cannot be placed directly inside them.']},
  {id:'react-003',level:'L1',title:'Components, props and one-way data flow',subtopic:'Components',what:'Components are reusable UI units. Props are inputs passed from a parent to a child, and React conventionally uses one-way data flow from parent to child.',how:'The parent owns or receives data and passes it through props. The child renders from those props and can request changes by invoking callback props supplied by the parent.',code:`function UserCard({ user, onSelect }) {\n  return (\n    <button onClick={() => onSelect(user.id)}>\n      {user.name}\n    </button>\n  );\n}` ,delivery:'Props are read-only inputs to a component. If a child needs to change parent-owned state, I pass a callback down rather than mutating the prop.',followups:['Props vs state?','How do you pass data child to parent?','What is prop drilling?'],traps:['Never mutate props.','A callback is still just a function passed as a prop.']},
  {id:'react-004',level:'L1',title:'State with useState',subtopic:'Hooks',what:'useState gives a function component local state and a setter that schedules a re-render.',how:'React associates each hook call with the component instance. Calling the setter schedules React to render the component again with the new state value.',code:`const [count, setCount] = useState(0);\n\nfunction increment() {\n  setCount(c => c + 1);\n}` ,delivery:'I use useState for local interactive state. When the next value depends on the previous value, I use the functional updater form to avoid stale-state assumptions.',followups:['Why functional updates?','Does setState update immediately?','Can state hold objects or arrays?'],traps:['Do not mutate an object or array in state. Create a new value instead.']},
  {id:'react-005',level:'L1',title:'Event handling in React',subtopic:'Foundations',what:'React event handlers are functions attached to JSX event props such as onClick and onChange.',how:'The handler runs when React processes the browser interaction. Event data can be read from the event argument, and the handler can update state.',code:`function SearchBox() {\n  const [query, setQuery] = useState('');\n  return <input value={query} onChange={e => setQuery(e.target.value)} />;\n}` ,delivery:'React uses event props such as onClick and onChange. I pass a function reference or callback rather than invoking the function while rendering.',followups:['Controlled vs uncontrolled input?','What is event bubbling?'],traps:['onClick={handleClick} is different from onClick={handleClick()}.']},
  {id:'react-006',level:'L1',title:'Rendering lists and why keys matter',subtopic:'Rendering',what:'Lists are usually rendered with map. Each sibling needs a stable key so React can track item identity across renders.',how:'React compares the previous and next element trees. Keys help it match the same logical item even when list order changes.',code:`users.map(user => (\n  <UserCard key={user.id} user={user} />\n))` ,delivery:'Keys provide identity for list items. I prefer a stable database or domain ID, especially when items can be inserted, removed, or reordered.',followups:['Why is array index a risky key?','What happens when a key changes?'],traps:['A key is used by React reconciliation; it is not automatically available as a component prop.']},
  {id:'react-007',level:'L1',title:'Conditional rendering',subtopic:'Rendering',what:'React uses normal JavaScript expressions to render different UI based on state or props.',how:'Common patterns are ternaries, logical AND, early returns, and small helper functions.',code:`return loading\n  ? <Spinner />\n  : error\n    ? <ErrorMessage />\n    : <Results items={items} />;` ,delivery:'I keep conditional rendering explicit. For mutually exclusive states like loading, error and data, I usually make the state machine clear rather than nesting many operators.',followups:['How do you avoid deeply nested JSX?'],traps:['Remember that 0 is rendered by && expressions, so Boolean conditions may be safer.']},
  {id:'react-008',level:'L1',title:'Controlled forms and validation',subtopic:'Forms',what:'A controlled form keeps input values in React state and uses handlers to update that state.',how:'The input value comes from state, onChange updates state, and submit validates the current state before making an API call.',code:`const [email, setEmail] = useState('');\n\n<form onSubmit={e => {\n  e.preventDefault();\n  if (!email.includes('@')) return;\n  submit(email);\n}}>\n  <input value={email} onChange={e => setEmail(e.target.value)} />\n</form>` ,delivery:'Controlled forms make the current form state explicit and let me validate, disable submit, show errors, and coordinate the form with application state.',followups:['Controlled vs uncontrolled forms?','How would you handle a large form?'],traps:['Always consider server-side validation too; frontend validation is not a security boundary.']},
  {id:'react-009',level:'L2',title:'useEffect: when and why to use it',subtopic:'Hooks',what:'useEffect is for synchronizing a component with an external system such as a network request, subscription, timer, or browser API.',how:'React runs the effect after a render is committed. The dependency array determines when the effect is re-synchronized, and an optional cleanup runs before the next effect or unmount.',code:`useEffect(() => {\n  const controller = new AbortController();\n  fetch('/api/users', { signal: controller.signal });\n  return () => controller.abort();\n}, []);` ,delivery:'I do not use useEffect for ordinary derived values. I use it when React needs to synchronize with something outside the render calculation, and I include the values the effect reads as dependencies.',followups:['What does the dependency array mean?','Why can an effect run twice in development?','How do you cancel fetch?'],traps:['Missing dependencies can create stale closures.','Do not use effects to calculate values that can be derived during render.']},
  {id:'react-010',level:'L2',title:'useMemo vs useCallback',subtopic:'Performance',what:'useMemo memoizes a calculated value; useCallback memoizes a function reference.',how:'Both can avoid recreating a value between renders when dependencies have not changed, but they should be used for a measured or meaningful performance reason.',code:`const filtered = useMemo(\n  () => products.filter(p => p.name.includes(query)),\n  [products, query]\n);\n\nconst select = useCallback(\n  id => setSelectedId(id),\n  []\n);` ,delivery:'useMemo is for memoizing a value and useCallback for a function reference. I use them selectively, usually when they prevent expensive work or unnecessary child renders.',followups:['Does useMemo guarantee caching forever?','When does React.memo help?'],traps:['Memoization has its own cost. Do not add it everywhere by default.']},
  {id:'react-011',level:'L2',title:'useRef and DOM references',subtopic:'Hooks',what:'useRef stores a mutable value that survives renders without causing a re-render when it changes. It can also point to a DOM element.',how:'React returns the same ref object for the component instance. Updating ref.current does not trigger rendering.',code:`const inputRef = useRef(null);\n\nfunction focusSearch() {\n  inputRef.current?.focus();\n}\n\n<input ref={inputRef} />` ,delivery:'I use useRef for imperative DOM access or mutable values that should persist between renders without being part of the rendered state.',followups:['useRef vs useState?','Can refs replace state?'],traps:['If a value affects what the user sees, it normally belongs in state or props, not only in a ref.']},
  {id:'react-012',level:'L2',title:'Custom hooks',subtopic:'Hooks',what:'A custom hook is a reusable function that composes React hooks and encapsulates stateful behavior.',how:'It follows hook rules and can return state, actions, or derived values to components. It shares logic, not component state itself.',code:`function useDebounce(value, delay) {\n  const [debounced, setDebounced] = useState(value);\n  useEffect(() => {\n    const id = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(id);\n  }, [value, delay]);\n  return debounced;\n}` ,delivery:'Custom hooks let me extract reusable stateful behavior without duplicating effects or event logic. Each component calling the hook gets its own hook state.',followups:['Rules of Hooks?','Custom hook vs utility function?'],traps:['A custom hook does not automatically create shared global state.']},
  {id:'react-013',level:'L2',title:'Context API and when to use it',subtopic:'State Management',what:'Context lets a component provide a value to descendants without passing it through every intermediate component as a prop.',how:'A provider supplies a value and consumers read it with useContext. A provider value change can cause consumers to re-render.',code:`const ThemeContext = createContext('light');\n\nfunction App() {\n  return <ThemeContext.Provider value="dark">\n    <Dashboard />\n  </ThemeContext.Provider>;\n}` ,delivery:'I use Context for cross-cutting values such as theme, locale or an authenticated user. I avoid turning Context into a dumping ground for every piece of application state.',followups:['Context vs Redux?','How can context cause unnecessary renders?'],traps:['Context is dependency injection for values, not automatically a complete state-management solution.']},
  {id:'react-014',level:'L2',title:'React Router and protected routes',subtopic:'Routing',what:'Client-side routing maps URLs to React views without requiring a full document navigation for every route.',how:'A router observes the URL and renders the matching route element. Protected routes commonly check authentication state before rendering private content.',code:`<Route path="/orders" element={\n  <RequireAuth><Orders /></RequireAuth>\n} />` ,delivery:'Routing is a frontend concern, but authorization must still be enforced by the backend. A protected React route improves UX; it cannot secure an API by itself.',followups:['Nested routes?','Route parameters?','How do you handle a 401?'],traps:['Never trust hidden routes or frontend role checks as the actual security boundary.']},
  {id:'react-015',level:'L2',title:'Calling Spring Boot REST APIs from React',subtopic:'API Integration',what:'React can call Spring Boot REST endpoints using fetch or an HTTP client, then represent loading, success and error states in the UI.',how:'A component or custom data hook starts the request, handles cancellation and errors, and updates state from the response.',code:`async function loadOrders(signal) {\n  const res = await fetch('/api/orders', { signal });\n  if (!res.ok) throw new Error('Request failed');\n  return res.json();\n}` ,delivery:'I treat the API contract as the boundary. The frontend handles loading, success and failure states, while Spring Boot owns validation, authorization and business rules.',followups:['CORS?','How do you attach JWT?','How do you handle 401/403?'],traps:['A 200 response does not guarantee valid business data; validate the contract and handle API errors.']},
  {id:'react-016',level:'L2',title:'Loading, error and empty states',subtopic:'API Integration',what:'A production data screen should distinguish loading, failure, successful data and successful-but-empty states.',how:'Model the request lifecycle explicitly rather than using one boolean. This keeps rendering predictable and avoids showing stale or contradictory UI.',code:`if (loading) return <Spinner />;\nif (error) return <ErrorState retry={reload} />;\nif (!orders.length) return <EmptyState />;\nreturn <OrderTable orders={orders} />;` ,delivery:'I model loading, error, empty and data states explicitly. That makes the UI resilient and gives the user a clear action when the backend fails.',followups:['Retry strategy?','How do you avoid stale responses?'],traps:['Empty data is not the same as an API error.']},
  {id:'react-017',level:'L2',title:'Debouncing search in React',subtopic:'Practical Patterns',what:'Debouncing delays an action until the user pauses typing, reducing unnecessary API requests.',how:'A timer is created whenever the input changes and cleared when the value changes again before the delay expires.',code:`useEffect(() => {\n  const id = setTimeout(() => search(query), 300);\n  return () => clearTimeout(id);\n}, [query]);` ,delivery:'For server-side search, I debounce the query so rapid typing does not generate one request per keystroke. I also cancel or ignore obsolete requests.',followups:['Debounce vs throttle?','How do you cancel previous requests?'],traps:['Debouncing improves request volume but does not replace backend pagination or indexing.']},
  {id:'react-018',level:'L2',title:'Pagination and filtering with a REST backend',subtopic:'API Integration',what:'Pagination keeps large result sets manageable by requesting only the records needed for the current view.',how:'React keeps page, size and filter state, sends them as query parameters, and renders returned content plus metadata such as total pages.',code:`GET /api/orders?page=0&size=20&status=SHIPPED` ,delivery:'I keep pagination and filters in URL or component state, pass them to Spring Boot as query parameters, and make the backend return both the current page and enough metadata for navigation.',followups:['Offset vs cursor pagination?','How would SQL support this efficiently?'],traps:['Do not fetch thousands of rows into the browser just to paginate them client-side.']},
  {id:'react-019',level:'L2',title:'JWT authentication in a React + Spring Security application',subtopic:'Security',what:'React can send credentials to a Spring Boot authentication endpoint and then use an issued access token when calling protected APIs.',how:'The backend authenticates the user, issues credentials according to its security design, and validates authorization on each protected request. The frontend controls presentation and request behavior.',code:`fetch('/api/orders', {\n  headers: { Authorization: \`Bearer \${token}\` }\n});` ,delivery:'The backend remains the security authority. React can manage login state and attach credentials, but Spring Security must validate the token and enforce authorization for every protected API.',followups:['Where should tokens be stored?','Refresh tokens?','CSRF with cookies?'],traps:['Do not say that React authenticates or authorizes the user by itself.']},
  {id:'react-020',level:'L3',title:'CORS in a React + Spring Boot application',subtopic:'Security',what:'CORS is a browser security mechanism that controls whether a frontend origin can read responses from a different origin.',how:'The browser sends CORS-related headers and may issue a preflight OPTIONS request for certain cross-origin calls. Spring Boot can configure allowed origins, methods and headers.',code:`@CrossOrigin(origins = "https://app.example.com")\n@RestController\nclass OrderController { }` ,delivery:'CORS is enforced by the browser, not by React. In production I configure the backend to allow the known frontend origin and only the methods and headers the application needs.',followups:['What is a preflight?','Why does Postman ignore CORS?','Credentials with CORS?'],traps:['CORS is not authentication.','Do not use allow-all origins casually in production.']},
  {id:'react-021',level:'L3',title:'React rendering, reconciliation and re-renders',subtopic:'Internals',what:'A state or prop change can cause a component function to run again. React then compares the resulting element tree and commits the necessary DOM changes.',how:'Element identity is influenced by type and key. Stable keys and component boundaries help React preserve the correct state when lists or trees change.',code:`function Counter() {\n  const [count, setCount] = useState(0);\n  console.log('render');\n  return <button onClick={() => setCount(c => c + 1)}>{count}</button>;\n}` ,delivery:'A re-render means React evaluates the component again; it does not mean the browser necessarily replaces the entire DOM. React reconciles the result and commits the required changes.',followups:['What causes a re-render?','React.memo?','Keys and state preservation?'],traps:['Avoid saying Virtual DOM automatically makes every React app fast.']},
  {id:'react-022',level:'L3',title:'Avoiding unnecessary re-renders',subtopic:'Performance',what:'Unnecessary renders can come from broad state ownership, changing object/function references, context updates, or expensive calculations.',how:'First identify the expensive component or calculation, then improve state placement, component boundaries, memoization or data flow where it provides measurable benefit.',code:`const UserRow = memo(function UserRow({ user, onSelect }) {\n  return <button onClick={() => onSelect(user.id)}>{user.name}</button>;\n});` ,delivery:'I optimize React based on evidence. I first inspect the render path, then reduce unnecessary state scope, stabilize references when needed, split components, or memoize expensive work.',followups:['React.memo vs useMemo?','How would you profile a slow page?'],traps:['Memoization cannot fix a poor data model or excessive network traffic.']},
  {id:'react-023',level:'L3',title:'Code splitting and lazy loading',subtopic:'Performance',what:'Code splitting loads JavaScript in smaller chunks so users do not need to download every feature before the first useful screen.',how:'Dynamic imports and React.lazy can defer a component bundle until it is needed. Suspense provides the loading UI.',code:`const Reports = lazy(() => import('./Reports'));\n\n<Suspense fallback={<Spinner />}>\n  <Reports />\n</Suspense>` ,delivery:'I use route-level or feature-level code splitting for large applications so the initial bundle stays smaller and secondary features load on demand.',followups:['What is a bundle?','Where would you split a large app?'],traps:['Lazy loading too many tiny chunks can add overhead and complexity.']},
  {id:'react-024',level:'L3',title:'Error boundaries',subtopic:'Reliability',what:'Error boundaries catch rendering errors in a component subtree and show fallback UI instead of allowing the entire UI tree to fail silently.',how:'They are commonly placed around route or feature boundaries so one broken feature can fail independently.',code:`<ErrorBoundary fallback={<ErrorPage />}>\n  <Reports />\n</ErrorBoundary>` ,delivery:'I place error boundaries around meaningful UI boundaries such as routes or major features. They improve resilience, but they do not replace API error handling or catch every asynchronous error.',followups:['What errors do boundaries catch?','Where should boundaries be placed?'],traps:['Do not claim an error boundary catches every promise rejection or event-handler error.']},
  {id:'react-025',level:'L3',title:'Frontend architecture for a large React application',subtopic:'Architecture',what:'A large React application benefits from clear feature boundaries, shared UI primitives, API/data access layers and predictable state ownership.',how:'I prefer organizing around business features rather than one huge components folder. Shared infrastructure stays reusable while feature-specific code remains close together.',code:`src/\n  app/\n  features/\n    orders/\n      components/\n      hooks/\n      api.js\n      pages/\n  shared/\n    ui/\n    utils/` ,delivery:'For a large app I organize around business features, keep API and state logic close to those features, and create shared components only when reuse is real.',followups:['Where does global state live?','How do you share API clients?','How would you structure tests?'],traps:['Folder structure alone does not create good architecture; dependency direction and ownership matter.']},
  {id:'react-026',level:'L3',title:'State management: local state vs Context vs external store',subtopic:'State Management',what:'The right state mechanism depends on scope and update frequency.',how:'Local state fits component-owned UI state. Context fits values needed across a subtree. An external store can help when many unrelated parts of the application need coordinated state and predictable updates.',code:`// local\nconst [open, setOpen] = useState(false);\n\n// context\nconst user = useContext(AuthContext);` ,delivery:'I start with the smallest state scope that solves the problem. I do not introduce a global store just because the application is large.',followups:['Redux vs Context?','Server state vs client state?'],traps:['Do not put fetched server data into global state automatically; consider the lifecycle and caching requirements first.']},
  {id:'react-027',level:'L3',title:'Testing React components',subtopic:'Testing',what:'Component tests verify user-visible behavior such as rendering, interaction, validation and API states.',how:'A useful test renders the component, performs realistic user actions, and asserts the resulting UI rather than its implementation details.',code:`render(<LoginForm onSubmit={mockSubmit} />);\nawait user.type(screen.getByLabelText(/email/i), 'a@b.com');\nawait user.click(screen.getByRole('button', { name: /login/i }));\nexpect(mockSubmit).toHaveBeenCalled();` ,delivery:'I prefer behavior-focused tests. I verify what the user can see and do, and I keep implementation details out of most component tests.',followups:['Unit vs integration tests?','How do you mock APIs?'],traps:['Avoid tests that only assert internal state or exact component structure.']},
  {id:'react-028',level:'L3',title:'Handling API race conditions',subtopic:'Reliability',what:'Race conditions occur when multiple requests are in flight and an older response arrives after a newer request.',how:'Cancellation with AbortController or request identity checks can prevent obsolete responses from updating current UI state.',code:`useEffect(() => {\n  const controller = new AbortController();\n  load(query, controller.signal);\n  return () => controller.abort();\n}, [query]);` ,delivery:'For changing queries, I cancel obsolete requests where possible and ensure an older response cannot overwrite the latest state. This matters in search and rapidly changing filters.',followups:['AbortController?','What if the server cannot cancel work?'],traps:['Debouncing alone does not guarantee that an older response cannot arrive later.']},
  {id:'react-029',level:'L3',title:'Environment configuration and frontend secrets',subtopic:'Production',what:'Frontend build variables configure things such as API base URLs, but values shipped to the browser must be considered public.',how:'Build tooling injects selected environment variables into the client bundle. Secrets such as private API keys must remain on the server.',code:`const API_BASE = import.meta.env.VITE_API_BASE_URL;\nfetch(\`\${API_BASE}/orders\`);` ,delivery:'Anything bundled into a browser application can be inspected by the user. I use environment variables for configuration, not for protecting secrets, and keep sensitive credentials on the backend.',followups:['How do you configure dev vs prod?','Where should API secrets live?'],traps:['Never put database passwords or private service credentials in React environment variables.']},
  {id:'react-030',level:'L3',title:'End-to-end React + Spring Boot request flow',subtopic:'Full Stack',what:'A full-stack request crosses browser rendering, frontend state, HTTP, backend security, business logic, persistence and response handling.',how:'A user action updates React state and triggers an HTTP request. Spring Security authenticates/authorizes, the controller validates input, services execute business logic, repositories access data, and the response drives the next UI state.',code:`React UI\n  -> fetch('/api/orders')\n  -> Spring Security\n  -> Controller\n  -> Service\n  -> Repository\n  -> Database\n  -> JSON response\n  -> React state\n  -> UI` ,delivery:'I debug full-stack issues by tracing the request end-to-end rather than assuming the problem is in React or Spring Boot. I check browser state and network first, then API logs, security, service logic and database behavior.',followups:['Where would you add correlation IDs?','How would you troubleshoot 500 vs 401 vs CORS?'],traps:['Do not fix a backend authorization problem by hiding a button in React.']}
,
  {"id":"react-031","level":"L1","title":"Component composition with children","subtopic":"Components","what":"Composition lets a component accept nested React elements through children instead of inheriting behavior from another component.","how":"A container controls layout and behavior while callers provide the content. This creates flexible boundaries without deep inheritance trees.","code":"function Panel({ children }) {\\n  return <section className=\"panel\">{children}</section>;\\n}","delivery":"I prefer composition in React. A reusable component can own layout and behavior while children or explicit props provide the content.","followups":["children vs explicit props?","When would inheritance be useful?"],"traps":["Do not describe children as inheritance.","Avoid overly generic components with dozens of configuration props."]},
  {"id":"react-032","level":"L1","title":"Lifting state up","subtopic":"State Management","what":"Lifting state up means moving shared state to the closest common parent that needs to coordinate multiple children.","how":"The parent becomes the source of truth and passes values down with props and updates down with callback props.","code":"function Parent() {\\n  const [selectedId, setSelectedId] = useState(null);\\n  return <><List selectedId={selectedId} onSelect={setSelectedId} /><Details id={selectedId} /></>;\\n}","delivery":"When siblings need to stay synchronized, I lift their shared state to the nearest common owner rather than maintaining duplicate state.","followups":["What is a single source of truth?","When should state remain local?"],"traps":["Do not lift every state value to the application root."]},
  {"id":"react-033","level":"L1","title":"Derived state vs duplicated state","subtopic":"State Management","what":"Derived state is calculated from existing props or state. Storing a second copy can introduce synchronization bugs.","how":"If the calculation is cheap, derive it during render. Memoize only when expensive work is measured to matter.","code":"const visible = products.filter(p => p.category === category);","delivery":"I keep one source of truth and derive values when possible. Duplicated state often creates bugs because two values can drift apart.","followups":["When should derived data use useMemo?","Why is duplicated state risky?"],"traps":["Do not use an effect just to mirror one state variable into another."]},
  {"id":"react-034","level":"L2","title":"useReducer for complex state transitions","subtopic":"Hooks","what":"useReducer manages state through a reducer that maps the current state and an action to the next state.","how":"It is useful when several related transitions form a small state machine or when many handlers update the same state shape.","code":"function reducer(state, action) {\\n  switch (action.type) {\\n    case \"success\": return { ...state, status: \"success\", data: action.data };\\n    case \"error\": return { ...state, status: \"error\", error: action.error };\\n    default: return state;\\n  }\\n}","delivery":"I use useReducer when related state transitions become complex enough that explicit actions and a pure reducer make the behavior easier to reason about.","followups":["useReducer vs useState?","Can reducers perform side effects?"],"traps":["Reducers should be pure."]},
  {"id":"react-035","level":"L2","title":"Context performance and provider boundaries","subtopic":"State Management","what":"Context consumers can re-render when the provider value they read changes.","how":"Split unrelated contexts and keep provider values stable when useful. Measure before adding memoization.","code":"const value = useMemo(() => ({ user, logout }), [user, logout]);","delivery":"For frequently changing context, I consider provider boundaries and value identity so unrelated consumers do not receive broad updates.","followups":["Does React.memo stop context updates?","When should contexts be split?"],"traps":["Context is not automatically a replacement for every external state store."]},
  {"id":"react-036","level":"L2","title":"Controlled vs uncontrolled inputs","subtopic":"Forms","what":"Controlled inputs receive their current value from React state; uncontrolled inputs let the DOM own the current value.","how":"Controlled inputs are useful for validation and coordinated UI. Uncontrolled inputs can be simpler when React does not need every keystroke.","code":"const [name, setName] = useState(\"\");\\n<input value={name} onChange={e => setName(e.target.value)} />","delivery":"I choose controlled or uncontrolled inputs based on requirements. Controlled forms make React state explicit, while uncontrolled fields can reduce wiring for simple cases.","followups":["When are uncontrolled inputs useful?","How do file inputs work?"],"traps":["Frontend validation is not a security boundary."]},
  {"id":"react-037","level":"L2","title":"AbortController for React data fetching","subtopic":"Data Fetching","what":"AbortController lets fetch observe cancellation when a request is no longer relevant.","how":"Create a controller per request, pass its signal, and abort it during effect cleanup or when replacing an obsolete request.","code":"useEffect(() => {\\n  const controller = new AbortController();\\n  fetch(\"/api/orders\", { signal: controller.signal });\\n  return () => controller.abort();\\n}, []);","delivery":"I cancel obsolete browser requests where possible, especially when a component unmounts or a changing query makes an earlier request irrelevant.","followups":["Does cancellation stop server processing?","What happens when fetch is aborted?"],"traps":["Client cancellation does not guarantee the server stopped work."]},
  {"id":"react-038","level":"L2","title":"Optimistic UI updates","subtopic":"Data Fetching","what":"Optimistic UI updates the interface before the server confirms the operation and rolls back if the request fails.","how":"Apply a reversible local change, send the request, then reconcile with server data or restore the previous state on failure.","code":"setTodos(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));","delivery":"I use optimistic updates when success is likely and rollback semantics are clear, such as toggling a task or like.","followups":["When should optimistic updates be avoided?","How do you handle concurrent edits?"],"traps":["The server remains authoritative."]},
  {"id":"react-039","level":"L2","title":"Pagination and URL state","subtopic":"Data Fetching","what":"Pagination limits the amount of data fetched and rendered at once. Page numbers and cursors are common API strategies.","how":"The frontend keeps the current page or cursor and requests that slice. Shareable pagination and filters can be represented in the URL.","code":"const params = new URLSearchParams({ page: String(page), size: \"20\" });\\nfetch(`/api/orders?${params}`);","delivery":"I treat pagination as both an API and UI concern. Cursor pagination is often useful for large changing datasets, while URL state improves shareability.","followups":["Offset vs cursor pagination?","When should pagination be in the URL?"],"traps":["Do not put secrets in query parameters."]},
  {"id":"react-040","level":"L2","title":"Reusable table and list component design","subtopic":"Architecture","what":"Reusable data-display components separate generic presentation from domain-specific fetching and business rules.","how":"A table can accept rows, columns, loading state and render callbacks while a feature owns its API and business behavior.","code":"<DataTable rows={orders} columns={columns} renderCell={renderCell} />","delivery":"I keep shared UI components generic and keep business rules inside feature modules. I only abstract after reuse is clear.","followups":["When does abstraction become harmful?","How would you design a reusable table?"],"traps":["Do not build a universal component before understanding its real reuse cases."]},
  {"id":"react-041","level":"L3","title":"React reconciliation and component identity","subtopic":"Internals","what":"Reconciliation compares the new element tree with the previous one to determine which updates are needed. Identity affects state preservation.","how":"Stable element types and keys help React match logical component instances across renders. Changing identity can recreate a subtree.","code":"items.map(item => <Editor key={item.id} item={item} />)","delivery":"I explain reconciliation through identity: stable types and keys help React determine which component instance corresponds to which new element.","followups":["How does changing a key reset state?","Why do keys matter beyond warnings?"],"traps":["Do not describe reconciliation as blindly comparing every DOM node."]},
  {"id":"react-042","level":"L3","title":"React.memo and referential equality","subtopic":"Performance","what":"React.memo can skip a component render when its props compare equal, normally through shallow comparison.","how":"It helps when a component renders often with stable props and its render work is meaningful. New object and function references can defeat shallow equality.","code":"const Row = React.memo(function Row({ user }) {\\n  return <div>{user.name}</div>;\\n});","delivery":"I use React.memo after identifying unnecessary renders and only when stable props make the optimization worthwhile.","followups":["React.memo vs useMemo?","Why can object props break memoization?"],"traps":["Memoization is an optimization, not a correctness requirement."]},
  {"id":"react-043","level":"L3","title":"Transitions for non-urgent updates","subtopic":"Advanced React","what":"A transition marks an update as non-urgent so React can prioritize more urgent interactions.","how":"The UI can remain responsive while React works on the transition. This is useful for expensive filtering or navigation updates.","code":"const [isPending, startTransition] = useTransition();\\nstartTransition(() => setFilter(nextFilter));","delivery":"I use transitions when an update can be deferred without delaying direct feedback, such as rendering a large filtered result set.","followups":["Urgent vs transition updates?","How is useDeferredValue different?"],"traps":["A transition does not make CPU work intrinsically faster."]},
  {"id":"react-044","level":"L3","title":"Frontend authorization vs backend authorization","subtopic":"Security","what":"Frontend authorization controls visible UI while backend authorization enforces whether an operation is allowed.","how":"The backend validates identity and permissions on protected requests. React checks improve UX but cannot be the security boundary.","code":"{user.canDelete && <button onClick={deleteOrder}>Delete</button>}","delivery":"I hide unauthorized controls for usability, but I always enforce authorization again in Spring Security or the backend service.","followups":["What happens if a hidden button is called manually?","RBAC vs ABAC?"],"traps":["A hidden or disabled button is not authorization."]},
  {"id":"react-045","level":"L3","title":"React observability and frontend-backend correlation","subtopic":"Production","what":"Frontend observability captures errors and performance signals and can connect browser requests to backend traces.","how":"Correlation IDs or trace context, client error reporting and performance telemetry help trace a user-visible failure through the API and backend services.","code":"reportError(error, { route: location.pathname, requestId });","delivery":"For production debugging I want a request or trace identifier connecting the browser request with backend logs, plus client-side error and performance telemetry.","followups":["What should never be logged?","How do you correlate frontend and backend logs?"],"traps":["Never log passwords, tokens or sensitive personal data for convenience."]},
{"id": "react-046", "level": "L2", "title": "Lifting state up", "subtopic": "State Management", "what": "Lifting state up means moving shared state to the closest common parent of components that need it.", "how": "The parent owns the source of truth and passes the current value and callbacks to children. This keeps sibling components synchronized without duplicating state.", "code": "function Parent() {\n  const [query, setQuery] = useState('');\n  return <><Search value={query} onChange={setQuery} /><Results query={query} /></>;\n}", "delivery": "When two components need the same changing value, I lift that state to their closest common owner and pass data down with callbacks.", "followups": ["When should state stay local?", "What is derived state?"], "traps": ["Do not lift state higher than necessary; excessive lifting can create prop drilling and unnecessary renders."]},
{"id": "react-047", "level": "L2", "title": "Derived state vs stored state", "subtopic": "State Management", "what": "Derived state is a value that can be calculated from existing props or state and usually should not be stored separately.", "how": "Calculate derived values during render or with memoization when computation is expensive. Store state only when the value represents independent user or application state.", "code": "const total = useMemo(() => items.reduce((sum, item) => sum + item.price, 0), [items]);", "delivery": "I avoid duplicating state when a value can be derived from existing state. One source of truth reduces synchronization bugs.", "followups": ["When is useMemo justified?", "What problems does duplicated state cause?"], "traps": ["Do not use an effect just to copy one piece of state into another derived value."]},
{"id": "react-048", "level": "L2", "title": "useReducer for complex state transitions", "subtopic": "Hooks", "what": "useReducer centralizes related state transitions in a reducer function and is useful when state changes have multiple actions or dependencies.", "how": "The component dispatches an action. The reducer receives the current state and action and returns the next state without mutating the previous state.", "code": "function reducer(state, action) {\n  if (action.type === 'success') return { ...state, loading: false, data: action.data };\n  return state;\n}", "delivery": "I prefer useReducer when several related state fields change together or when explicit actions make transitions easier to reason about.", "followups": ["useReducer vs useState?", "Can a reducer perform API calls?"], "traps": ["Keep reducers pure; side effects belong outside the reducer."]},
{"id": "react-049", "level": "L2", "title": "Stale closures in React", "subtopic": "Hooks", "what": "A stale closure occurs when a callback retains values from an older render and later uses those outdated values.", "how": "Functions created during render close over that render's variables. Functional state updates, correct effect dependencies, or refs can address different stale-value cases.", "code": "setCount(current => current + 1);", "delivery": "I recognize that callbacks close over render values. I fix stale state with functional updates when the next state depends on the previous state, and I fix effects with accurate dependencies.", "followups": ["Why does setTimeout see old state?", "When is a ref useful for latest values?"], "traps": ["Do not solve every stale-closure problem by disabling the dependency lint rule."]},
{"id": "react-050", "level": "L2", "title": "State batching in React", "subtopic": "Rendering", "what": "State batching groups multiple state updates so React can process them together and avoid unnecessary renders.", "how": "React can batch updates triggered during the same interaction and, in modern React, many asynchronous contexts as well. Functional updates are important when multiple updates depend on previous state.", "code": "setCount(c => c + 1);\nsetCount(c => c + 1);", "delivery": "Batching reduces redundant renders. When I make multiple updates based on previous state, I use functional updates so each update receives the latest queued value.", "followups": ["Are state setters synchronous?", "Why does logging state immediately show the old value?"], "traps": ["Do not rely on reading state immediately after calling its setter as proof that the value changed."]},
{"id": "react-051", "level": "L2", "title": "State preservation and resetting with keys", "subtopic": "Rendering", "what": "React preserves state when it considers an element the same component identity, and changing its key can intentionally create a new identity.", "how": "Element type, position and keys influence identity. A new key causes React to discard the previous instance's state for that subtree.", "code": "<Chat key={conversationId} conversationId={conversationId} />", "delivery": "Keys are not only for lists. I can deliberately change a key when I need React to reset a component's local state for a new logical entity.", "followups": ["How do keys affect reconciliation?", "Can changing a key be expensive?"], "traps": ["Do not use changing keys as a general fix for state bugs without understanding the reset behavior."]},
{"id": "react-052", "level": "L3", "title": "Context and unnecessary re-renders", "subtopic": "State Management", "what": "Consumers of a context can re-render when the provider value changes, so unstable provider values can cause avoidable work.", "how": "A provider publishes a value to its consumers. If the value object is recreated every render, consumers may observe a new reference even when the meaningful data did not change.", "code": "const value = useMemo(() => ({ user, logout }), [user, logout]);\nreturn <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;", "delivery": "I use context for cross-cutting data, but I watch provider value identity and split contexts when unrelated consumers should not re-render together.", "followups": ["When should you split context?", "Context vs Redux?"], "traps": ["Context is dependency injection for data, not automatically a complete state-management architecture."]},
{"id": "react-053", "level": "L3", "title": "Request race conditions in React", "subtopic": "Async Data", "what": "A request race condition occurs when an older request finishes after a newer request and incorrectly overwrites the latest UI state.", "how": "Search terms or changing IDs can start overlapping requests. AbortController or request identity checks prevent stale responses from winning.", "code": "const controller = new AbortController();\nfetch(`/api/search?q=${query}`, { signal: controller.signal });\nreturn () => controller.abort();", "delivery": "For changing requests I make the request lifecycle explicit and cancel or ignore stale responses so an older request cannot overwrite newer data.", "followups": ["How does AbortController work?", "What about libraries such as React Query?"], "traps": ["Debouncing alone does not guarantee that responses arrive in order."]},
{"id": "react-054", "level": "L3", "title": "Optimistic UI updates", "subtopic": "Async Data", "what": "An optimistic update changes the UI before the server confirms success, then reconciles or rolls back if the request fails.", "how": "Keep enough previous state to restore on failure, send the mutation, and replace the optimistic result with authoritative server data when appropriate.", "code": "setLiked(true);\ntry { await likePost(id); } catch { setLiked(false); }", "delivery": "I use optimistic updates for interactions where failure is recoverable and the expected result is predictable, while keeping a rollback path and server as the source of truth.", "followups": ["When should you avoid optimistic updates?", "How do you handle concurrent mutations?"], "traps": ["Do not optimistically update security-sensitive or irreversible operations without careful reconciliation."]},
{"id": "react-055", "level": "L3", "title": "Error boundaries", "subtopic": "Production", "what": "An error boundary catches rendering errors in a descendant tree and lets the application show fallback UI instead of crashing the entire visible tree.", "how": "Error boundaries are implemented with supported boundary APIs and can log the error and render a recovery experience. They do not catch every asynchronous or event-handler error automatically.", "code": "<ErrorBoundary fallback={<ErrorPage />}><Orders /></ErrorBoundary>", "delivery": "I use error boundaries around meaningful UI regions so a rendering failure can degrade gracefully and be reported without taking down the whole application.", "followups": ["What errors do boundaries not catch?", "Where should boundaries be placed?"], "traps": ["Do not claim an error boundary catches all JavaScript errors everywhere in the application."]},
{"id": "react-056", "level": "L3", "title": "Suspense and lazy loading", "subtopic": "Performance", "what": "React.lazy can defer loading a component module, while Suspense provides fallback UI while a supported resource is not ready.", "how": "The bundler creates a separate chunk for a lazily imported module. Suspense displays a fallback until React can render the suspended subtree.", "code": "const Admin = lazy(() => import('./Admin'));\n<Suspense fallback={<Spinner />}><Admin /></Suspense>", "delivery": "I use lazy loading to reduce initial JavaScript for routes or heavy features, and Suspense to provide a controlled loading experience around supported asynchronous boundaries.", "followups": ["What is code splitting?", "Can Suspense replace all loading state?"], "traps": ["Do not treat Suspense as a universal data-fetching API without considering the framework or library providing the integration."]},
{"id": "react-057", "level": "L3", "title": "React rendering performance diagnosis", "subtopic": "Performance", "what": "Performance optimization starts by identifying expensive renders or computations rather than adding memoization everywhere.", "how": "Use the React DevTools Profiler and browser performance tools to find components that render frequently or spend significant time rendering. Then optimize the actual bottleneck.", "code": "const Row = React.memo(RowComponent);", "delivery": "I profile first, identify the expensive path, then choose memoization, state colocation, virtualization, or architectural changes based on evidence.", "followups": ["What would you look for in the Profiler?", "When is virtualization useful?"], "traps": ["Do not equate fewer renders with better performance if each render is cheap or memoization overhead is higher."]},
{"id": "react-058", "level": "L3", "title": "Component composition over prop drilling", "subtopic": "Architecture", "what": "Composition lets a parent pass behavior or UI regions as children or props instead of threading many unrelated values through intermediate components.", "how": "Create components that accept children or specialized slots so intermediate components do not need to understand data they only forward.", "code": "<PageLayout sidebar={<Filters />}><Orders /></PageLayout>", "delivery": "Before reaching for global state, I consider composition and colocated state. It can remove prop drilling while keeping dependencies explicit.", "followups": ["Composition vs inheritance?", "When is context better?"], "traps": ["Do not make every component configurable through dozens of props; keep boundaries focused."]},
{"id": "react-059", "level": "L3", "title": "Client state vs server state", "subtopic": "Architecture", "what": "Client state represents local UI concerns, while server state is data owned by a backend and subject to caching, synchronization and invalidation.", "how": "Local state handles things like modal visibility. Server-state libraries can manage fetching, caching, retries, stale data and mutations instead of manually recreating those mechanisms in components.", "code": "const [isOpen, setIsOpen] = useState(false);", "delivery": "I distinguish UI state from server state. That prevents me from putting every API response into a global client store when a query cache may be a better fit.", "followups": ["What belongs in Redux?", "Why is caching server data difficult?"], "traps": ["Do not assume every piece of remote data should live permanently in global client state."]},
{"id": "react-060", "level": "L3", "title": "React Strict Mode in development", "subtopic": "Production", "what": "Strict Mode enables additional development-time checks that help reveal unsafe patterns and unexpected side effects.", "how": "Development behavior can intentionally invoke certain render or effect-related paths more than once to expose code that is not resilient to re-running setup and cleanup.", "code": "<StrictMode><App /></StrictMode>", "delivery": "I treat Strict Mode behavior as a development diagnostic rather than a production behavior to work around. Effects should have correct setup and cleanup semantics.", "followups": ["Why can an effect appear to run twice?", "Should Strict Mode be disabled?"], "traps": ["Do not add flags to hide duplicate development behavior instead of fixing non-idempotent side effects."]},
{"id": "react-061", "level": "L2", "title": "Functional components and render purity", "subtopic": "Components", "what": "A React render should be a pure calculation of UI from props, state and context.", "how": "React may render a component more than once, so render logic should not mutate external state, perform network calls or depend on one-time execution.", "code": "function Price({ amount }) {\n  const formatted = amount.toFixed(2);\n  return <span>{formatted}</span>;\n}", "delivery": "I keep render functions pure and move side effects to event handlers or effects when synchronization with an external system is actually required.", "followups": ["Why can React render twice in development?", "What counts as a side effect?"], "traps": ["Do not put API calls, subscriptions or mutations directly in the component render body."]},
{"id": "react-062", "level": "L2", "title": "Functional state updates", "subtopic": "State Management", "what": "A functional state update derives the next state from the previous state supplied by React.", "how": "It is the safe form when multiple updates may be queued or when the next value depends on the previous value.", "code": "setCount(c => c + 1);\nsetCount(c => c + 1);", "delivery": "When the next state depends on previous state, I use the functional updater so React can apply each update against the latest queued value.", "followups": ["Why can setCount(count + 1) lose an update?", "Are state updates synchronous?"], "traps": ["Do not use a closed-over state value when several queued updates depend on the previous value."]},
{"id": "react-063", "level": "L2", "title": "Avoiding unnecessary derived state", "subtopic": "State Management", "what": "If a value can be calculated directly from existing props or state, storing another copy can create synchronization bugs.", "how": "Calculate cheap derived values during render. Use memoization only when profiling shows the calculation is expensive.", "code": "const fullName = `${firstName} ${lastName}`;", "delivery": "I prefer one source of truth. I derive simple values during render instead of storing duplicate state and trying to synchronize it.", "followups": ["When is derived state justified?", "When would you use useMemo?"], "traps": ["Do not add an effect just to copy one state value into another derived value."]},
{"id": "react-064", "level": "L2", "title": "Effect cleanup and subscriptions", "subtopic": "Effects", "what": "An effect cleanup reverses work created by the effect when dependencies change or the component unmounts.", "how": "Subscriptions, timers, event listeners and abort controllers should be cleaned up so obsolete work does not continue.", "code": "useEffect(() => {\n  const onResize = () => setWidth(window.innerWidth);\n  window.addEventListener('resize', onResize);\n  return () => window.removeEventListener('resize', onResize);\n}, []);", "delivery": "I treat effect setup and cleanup as a pair. Anything the effect subscribes to or allocates should have a corresponding cleanup when necessary.", "followups": ["When does cleanup run?", "What happens when dependencies change?"], "traps": ["Do not assume cleanup runs only on unmount; dependency changes can trigger cleanup before the next setup."]},
{"id": "react-065", "level": "L2", "title": "useEffect versus event handlers", "subtopic": "Effects", "what": "Effects synchronize React with external systems; event handlers are usually the right place for work caused directly by a user action.", "how": "A click that submits an order should call the submit logic from the handler. An effect is better for synchronization such as subscribing to an external source when state changes.", "code": "function SaveButton({ save }) {\n  return <button onClick={save}>Save</button>;\n}", "delivery": "I avoid using effects as a general-purpose workflow engine. If an action is caused by a user event, I normally start it in the event handler.", "followups": ["When should an effect be used?", "Why can effect chains be problematic?"], "traps": ["Do not move ordinary event-driven business logic into effects just because it changes state."]},
{"id": "react-066", "level": "L2", "title": "useRef for mutable values", "subtopic": "Hooks", "what": "A ref stores a mutable value across renders without causing a re-render when its current value changes.", "how": "Use refs for DOM nodes or values such as timer IDs and latest mutable information that does not itself determine rendered output.", "code": "const timerRef = useRef(null);\ntimerRef.current = setTimeout(save, 500);", "delivery": "I use refs when I need persistent mutable storage that should not trigger rendering. If the value belongs in the UI, I use state instead.", "followups": ["useRef vs useState?", "Does changing ref.current re-render?"], "traps": ["Do not use refs to bypass React state for values that the UI needs to react to."]},
{"id": "react-067", "level": "L2", "title": "useMemo: what it actually guarantees", "subtopic": "Performance", "what": "useMemo caches a calculation result between renders when its dependencies remain unchanged.", "how": "React can reuse the memoized result, but memoization is a performance optimization rather than a semantic requirement for correctness.", "code": "const visible = useMemo(() => filter(items, query), [items, query]);", "delivery": "I use useMemo for measured expensive calculations or to stabilize a value when that identity matters. I do not add it to every calculation automatically.", "followups": ["Can React discard a memoized value?", "useMemo vs useCallback?"], "traps": ["Do not depend on useMemo for correctness or assume every memo makes an application faster."]},
{"id": "react-068", "level": "L2", "title": "useCallback and function identity", "subtopic": "Performance", "what": "useCallback memoizes a function reference until its dependencies change.", "how": "Stable function identity can help memoized children or dependency arrays, but creating callbacks is normally cheap and unnecessary memoization adds complexity.", "code": "const onSelect = useCallback((id) => setSelectedId(id), []);", "delivery": "I use useCallback when function identity is relevant to a measured optimization or a hook dependency, not simply because a component contains callbacks.", "followups": ["Why does a new function cause a memoized child to render?", "When can useCallback hurt readability?"], "traps": ["Do not claim useCallback prevents the function body from being recreated in every conceptual sense; it preserves the returned reference when dependencies are stable."]},
{"id": "react-069", "level": "L3", "title": "React.memo and shallow prop comparison", "subtopic": "Performance", "what": "React.memo can skip a child render when its props compare equal according to the memo comparison.", "how": "The default comparison is based on prop equality. New object, array or function references can therefore defeat memoization unless identities are intentionally stabilized or a custom comparison is appropriate.", "code": "const Row = React.memo(function Row({ item }) {\n  return <div>{item.name}</div>;\n});", "delivery": "I use React.memo selectively. I first establish that the child is expensive or frequently rendered, then make prop identity predictable enough for the optimization to matter.", "followups": ["What does React.memo compare?", "How do useMemo and useCallback interact with memo?"], "traps": ["Do not expect memo to prevent renders caused by the component's own state or context changes."]},
{"id": "react-070", "level": "L3", "title": "useTransition for non-urgent updates", "subtopic": "Concurrency", "what": "useTransition lets React mark certain state updates as non-urgent so more important interactions can remain responsive.", "how": "The transition update can be interrupted by more urgent work, and isPending can drive feedback while the transition is in progress.", "code": "const [isPending, startTransition] = useTransition();\nstartTransition(() => setFilter(value));", "delivery": "I use transitions for updates that can yield to urgent interactions, such as rendering a large filtered result, rather than for operations that must happen immediately.", "followups": ["What is urgent vs non-urgent work?", "Does startTransition make network requests faster?"], "traps": ["Do not describe a transition as a server-side performance optimization or a guarantee that work finishes sooner."]},
{"id": "react-071", "level": "L3", "title": "useDeferredValue for expensive rendering", "subtopic": "Concurrency", "what": "useDeferredValue lets a component render a deferred version of a value so urgent updates can stay responsive.", "how": "The source value updates immediately while React may delay work that depends on the deferred value.", "code": "const deferredQuery = useDeferredValue(query);\nreturn <Results query={deferredQuery} />;", "delivery": "I use deferred values when the input itself must feel immediate but rendering the result for every keystroke is expensive.", "followups": ["useDeferredValue vs debounce?", "Does it delay the source state?"], "traps": ["A deferred render is not the same as debouncing a network request; it does not by itself reduce API calls."]},
{"id": "react-072", "level": "L3", "title": "useId and stable IDs for accessibility", "subtopic": "Forms", "what": "useId generates IDs that are stable across server and client rendering for associating related elements.", "how": "Use the generated ID for relationships such as label-for and aria-describedby. It is not intended as a list key or database identifier.", "code": "const id = useId();\n<label htmlFor={id}>Email</label>\n<input id={id} />", "delivery": "I use useId for accessibility relationships and hydration-safe IDs. I do not use it as a business identifier or list key.", "followups": ["Why not use random IDs during render?", "Can useId be used for keys?"], "traps": ["Do not use useId for data identity; keys should come from the data model when possible."]},
{"id": "react-073", "level": "L3", "title": "Portals and rendering outside the DOM hierarchy", "subtopic": "Advanced UI", "what": "A portal renders React children into a different DOM node while preserving their place in the React tree.", "how": "Portals are useful for modals, dialogs and overlays that need different DOM positioning or stacking behavior while retaining React context and event relationships.", "code": "createPortal(<Modal />, document.getElementById('modal-root'));", "delivery": "I use portals for overlays that need to escape DOM layout constraints. The component remains part of the React tree even though its DOM is mounted elsewhere.", "followups": ["Do events bubble through portals?", "Why use a portal for a modal?"], "traps": ["Do not assume a portal creates a separate React application or loses context automatically."]},
{"id": "react-074", "level": "L3", "title": "useImperativeHandle and imperative APIs", "subtopic": "Refs", "what": "useImperativeHandle customizes the value exposed through a ref to a component or DOM-facing API.", "how": "Expose a small imperative surface such as focus or reset when declarative props are not a good fit for the interaction.", "code": "useImperativeHandle(ref, () => ({ focus: () => inputRef.current?.focus() }), []);", "delivery": "I keep imperative handles narrow and use them for operations such as focus or reset. Most application state should remain declarative.", "followups": ["When is an imperative API justified?", "How does forwardRef relate to refs?"], "traps": ["Do not expose internal mutable state broadly through refs; it makes component behavior harder to reason about."]},
{"id": "react-075", "level": "L3", "title": "External stores and useSyncExternalStore", "subtopic": "State Management", "what": "useSyncExternalStore provides a supported way for React to subscribe to external mutable stores while keeping rendering consistent.", "how": "A store exposes a subscribe function and a snapshot getter. React uses those functions to know when the external value changes and what should be rendered.", "code": "const value = useSyncExternalStore(store.subscribe, store.getSnapshot);", "delivery": "When integrating an external store, I prefer React's supported subscription mechanism rather than manually forcing renders or reading mutable state during render.", "followups": ["Why is an external store different from Context?", "What is a snapshot?"], "traps": ["Do not manually mutate external data and expect React to notice without a subscription mechanism."]},
{"id": "react-076", "level": "L3", "title": "React hydration and server-rendered markup", "subtopic": "Rendering", "what": "Hydration attaches React behavior to HTML that was rendered on the server and expects the initial client render to match the server output.", "how": "The server sends HTML first, then the client hydrates it. Nondeterministic render output such as time-dependent values can cause hydration mismatches.", "code": "hydrateRoot(document.getElementById('root'), <App />);", "delivery": "For SSR applications I keep the initial render deterministic between server and client and treat hydration warnings as correctness problems rather than cosmetic messages.", "followups": ["What causes hydration mismatch?", "SSR vs CSR?"], "traps": ["Do not hide hydration mismatches by suppressing warnings without understanding why server and client output differ."]},
{"id": "react-077", "level": "L3", "title": "Avoiding effect dependency bugs", "subtopic": "Effects", "what": "Effect dependencies describe the reactive values used by the effect so React can resynchronize when those values change.", "how": "If a dependency is omitted, the effect can capture stale values. If unstable values are included unnecessarily, the effect can rerun too often.", "code": "useEffect(() => {\n  connect(roomId);\n  return () => disconnect(roomId);\n}, [roomId]);", "delivery": "I treat the dependency array as part of the effect's synchronization contract. I fix the code or structure rather than silencing dependency warnings blindly.", "followups": ["Why do functions appear as dependencies?", "How do you stabilize an object dependency?"], "traps": ["Do not remove dependencies just to make an effect run less often; that can create stale behavior."]},
{"id": "react-078", "level": "L3", "title": "State colocation and component boundaries", "subtopic": "Architecture", "what": "State colocation keeps state close to the components that use it, reducing unnecessary propagation and making ownership clearer.", "how": "Move state down until multiple consumers genuinely need a common owner. Split large components when unrelated state and rendering logic become coupled.", "code": "function SearchBox() {\n  const [query, setQuery] = useState('');\n  return <input value={query} onChange={e => setQuery(e.target.value)} />;\n}", "delivery": "I colocate state by default and lift it only when coordination requires a higher owner. This often reduces prop drilling and unnecessary re-renders.", "followups": ["When should state move to Context?", "How does colocation help performance?"], "traps": ["Do not interpret colocation as keeping all state local even when multiple features need the same source of truth."]},
{"id": "react-079", "level": "L3", "title": "Frontend error handling strategy", "subtopic": "Reliability", "what": "Robust React applications distinguish rendering failures, network failures, validation errors and business errors and present appropriate recovery paths.", "how": "Use error boundaries for rendering failures, explicit request state for API failures, field-level validation for forms and user-friendly recovery actions for expected failures.", "code": "if (status === 'error') return <Retry onRetry={reload} />;", "delivery": "I design error handling by failure type. A rendering error boundary is different from an API error state, and both should provide a useful recovery path.", "followups": ["Where should API errors be handled?", "How do you log frontend failures?"], "traps": ["Do not show raw backend stack traces or treat every HTTP failure as the same user experience."]},
{"id": "react-080", "level": "L3", "title": "React performance optimization checklist", "subtopic": "Performance", "what": "React performance work should reduce actual user-visible bottlenecks rather than optimize every component by default.", "how": "Profile first, then consider state colocation, memoization, virtualization, code splitting, deferred rendering and reducing expensive work or unnecessary data updates.", "code": "const Row = memo(RowComponent);\nconst deferredQuery = useDeferredValue(query);", "delivery": "My order is measure, identify the bottleneck, choose the smallest effective optimization, and measure again. I avoid speculative memoization.", "followups": ["How would you profile a slow page?", "When would you virtualize a list?"], "traps": ["Do not optimize based only on render counts; measure actual render cost and user impact."]}
,
{"id":"react-081","level":"L2","title":"Feature-based component organization","subtopic":"Architecture","what":"Organizing React by business feature keeps related UI, hooks, API calls and tests close together and reduces cross-feature coupling.","how":"A feature such as orders can contain its page, components, hooks, API client functions and tests. Shared primitives remain in a separate common layer.","code":"src/features/orders/\n  OrdersPage.jsx\n  OrderTable.jsx\n  useOrders.js\n  ordersApi.js\n  OrdersPage.test.jsx","delivery":"For a growing application, I prefer feature-oriented boundaries because they map code ownership to business capabilities and make changes easier to localize.","followups":["Feature folder vs layer folder?", "What belongs in shared code?"],"traps":["Do not put every component into one global components folder.", "Do not create shared abstractions before reuse is clear."]},
{"id":"react-082","level":"L2","title":"Container and presentational responsibilities","subtopic":"Architecture","what":"A useful separation is to keep data orchestration and stateful behavior distinct from reusable presentation, while avoiding rigid two-component rules everywhere.","how":"A page or feature hook can fetch and transform data, while focused components receive data and callbacks. Modern React often uses custom hooks and composition instead of the old container-component pattern.","code":"function OrdersPage() {\n  const { orders, loading } = useOrders();\n  return <OrderTable orders={orders} loading={loading} />;\n}","delivery":"I separate responsibilities around behavior and reuse, not around an arbitrary rule that every component must be either container or presentational.","followups":["When would you keep logic together?", "How do custom hooks change this pattern?"],"traps":["Do not create layers just for ceremony."]},
{"id":"react-083","level":"L2","title":"Reusable form architecture","subtopic":"Forms","what":"Large forms become difficult when field state, validation, submission and server errors are mixed together.","how":"Keep field values and validation rules predictable, isolate reusable field components, and represent server validation errors separately from client validation errors.","code":"function Field({ label, error, ...props }) {\n  return <label>{label}<input {...props} aria-invalid={!!error}/>{error && <span>{error}</span>}</label>;\n}","delivery":"For production forms, I separate field state, validation and server errors so each concern has a clear owner and the UI can report the right failure.","followups":["Controlled vs uncontrolled forms?", "How do you handle server validation?"],"traps":["Do not assume client validation replaces backend validation."]},
{"id":"react-084","level":"L2","title":"API client layer in React applications","subtopic":"Data Fetching","what":"Centralizing HTTP behavior avoids duplicating URL construction, headers, error parsing and authentication handling across components.","how":"Components or hooks call feature-specific API functions. The API layer handles transport concerns while UI code handles user-facing state.","code":"export async function getOrders(signal) {\n  const res = await fetch('/api/orders', { signal });\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);\n  return res.json();\n}","delivery":"I keep HTTP transport details out of presentation components. That makes API behavior easier to test and change without rewriting the UI.","followups":["Where should auth headers be added?", "How do you test the API layer?"],"traps":["Do not hide business logic inside a generic HTTP helper."]},
{"id":"react-085","level":"L2","title":"Query state versus server state","subtopic":"Data Fetching","what":"URL query parameters and server data represent different kinds of state and should not automatically be copied into multiple local states.","how":"Use the URL for shareable navigation state such as filters or page number. Treat fetched data as server state with explicit loading, stale and error semantics.","code":"const params = new URLSearchParams({ page: String(page), q: query });\nwindow.history.replaceState(null, '', `?${params}`);","delivery":"I decide where state belongs based on ownership and lifetime: URL state is shareable navigation state, while server data belongs to a data-fetching strategy.","followups":["What should be in local state?", "Why avoid duplicated state?"],"traps":["Do not keep the same value independently in URL, component state and server cache without a synchronization plan."]},
{"id":"react-086","level":"L2","title":"Caching server data","subtopic":"Data Fetching","what":"Caching server responses can avoid repeated requests and make navigation feel faster, but cached data needs freshness and invalidation rules.","how":"A server-state library or a carefully designed cache can deduplicate requests, track stale data and refetch after mutations.","code":"// Conceptual\n// query: orders\n// mutation: updateOrder\n// invalidate: orders","delivery":"I treat server data differently from local UI state. The important questions are freshness, deduplication, invalidation and refetch behavior.","followups":["Client cache vs browser HTTP cache?", "When should data be invalidated?"],"traps":["Do not assume cached data is always current."]},
{"id":"react-087","level":"L2","title":"Optimistic mutation with rollback","subtopic":"Data Fetching","what":"Optimistic UI updates the screen before the server confirms a mutation, then rolls back or reconciles if the request fails.","how":"Capture the previous state, apply the expected change, send the request, and restore or refetch when the server rejects it.","code":"setOrders(prev => prev.map(o => o.id === id ? { ...o, status: 'cancelled' } : o));\ntry { await cancelOrder(id); } catch { await refetch(); }","delivery":"Optimistic updates improve perceived latency, but I only use them when the expected result is predictable and failure recovery is clear.","followups":["When should you avoid optimistic UI?", "How do you prevent duplicate mutations?"],"traps":["Do not show success permanently before the server confirms the operation."]},
{"id":"react-088","level":"L2","title":"Reusable modal and portal pattern","subtopic":"UI Patterns","what":"A modal often needs to escape normal layout stacking and should manage focus, dismissal and accessibility.","how":"Render modal content through a portal into a dedicated DOM node, lock or manage background interaction, and restore focus when it closes.","code":"createPortal(\n  <dialog open aria-modal=\"true\">Confirm deletion?</dialog>,\n  document.getElementById('modal-root')\n);","delivery":"A production modal is more than a div with z-index. I consider portal placement, focus management, keyboard dismissal and accessibility.","followups":["Why use a portal?", "How do you trap focus?"],"traps":["Do not rely only on z-index to solve every overlay problem."]},
{"id":"react-089","level":"L2","title":"Accessible React components","subtopic":"Accessibility","what":"React applications should expose semantic HTML, labels, keyboard behavior and useful state information to assistive technologies.","how":"Prefer native elements when possible, associate labels with controls, use buttons for actions, and add ARIA only when native semantics are insufficient.","code":"<label htmlFor=\"email\">Email</label>\n<input id=\"email\" name=\"email\" />","delivery":"I start with semantic HTML and keyboard accessibility, then use ARIA to fill genuine semantic gaps rather than using ARIA as decoration.","followups":["How do you test accessibility?", "Button vs div with onClick?"],"traps":["Do not use clickable divs when a button or link is appropriate."]},
{"id":"react-090","level":"L2","title":"Keyboard navigation and focus management","subtopic":"Accessibility","what":"Single-page applications can change content without a full browser navigation, so focus management becomes part of the user experience.","how":"After route or modal changes, move focus intentionally to the relevant heading or control when appropriate and ensure all interactive elements are keyboard reachable.","code":"useEffect(() => {\n  headingRef.current?.focus();\n}, [location.pathname]);","delivery":"I treat focus as UI state that needs deliberate management when the application changes context without a full page reload.","followups":["How do you manage focus after form errors?", "What is a roving tabindex?"],"traps":["Do not steal focus on every render."]},
{"id":"react-091","level":"L2","title":"Error states that users can recover from","subtopic":"UX Patterns","what":"A useful error state explains what failed and gives the user an appropriate recovery action.","how":"Distinguish validation errors, authorization failures, transient network errors and unexpected application errors, then provide context-specific actions.","code":"if (error.code === 'NETWORK') {\n  return <RetryPanel onRetry={reload} />;\n}","delivery":"I avoid a generic error message for every failure. The UI should tell the user what they can do next while keeping technical details out of the screen.","followups":["Where should logging happen?", "How do you handle 401 vs 500?"],"traps":["Do not expose stack traces or internal exception details."]},
{"id":"react-092","level":"L2","title":"Loading skeletons versus spinners","subtopic":"UX Patterns","what":"Loading feedback should match the expected wait and preserve layout stability when possible.","how":"Skeletons work well for content-heavy regions because they reserve space; spinners are useful for short actions or small regions.","code":"return loading ? <OrderTableSkeleton /> : <OrderTable rows={orders} />;","delivery":"I choose loading feedback based on context and layout stability, not because one pattern is universally better.","followups":["How do you avoid layout shift?", "When should a button show a spinner?"],"traps":["Do not block the entire application for a request that only affects one panel."]},
{"id":"react-093","level":"L2","title":"Debounced search with request cancellation","subtopic":"Data Fetching","what":"Search boxes often generate many requests; debouncing reduces traffic and cancellation prevents older results from winning a race.","how":"Wait briefly after input stops, create an AbortController for each request, and abort the previous request when a new search begins.","code":"const controller = new AbortController();\nfetch(`/api/search?q=${encodeURIComponent(q)}`, { signal: controller.signal });","delivery":"For live search I combine debouncing with cancellation so the backend gets fewer requests and stale responses cannot overwrite newer results.","followups":["Debounce vs throttle?", "What happens when AbortController aborts?"],"traps":["Debouncing alone does not guarantee response ordering."]},
{"id":"react-094","level":"L2","title":"Pagination strategies in React","subtopic":"Data Fetching","what":"Pagination can be page-based or cursor-based, and the UI must keep its query state synchronized with the backend contract.","how":"Page pagination is simple for stable datasets. Cursor pagination is often better for large or frequently changing datasets because the cursor represents a position in an ordered result set.","code":"GET /api/orders?page=2&size=20\nGET /api/orders?cursor=eyJpZCI6MTIzfQ==&limit=20","delivery":"I choose pagination based on data volatility and API requirements rather than assuming page numbers are always sufficient.","followups":["Offset vs cursor pagination?", "How do you preserve filters when changing pages?"],"traps":["Do not use an unstable sort with cursor pagination."]},
{"id":"react-095","level":"L2","title":"File upload progress and cancellation","subtopic":"Data Fetching","what":"File uploads need client-side validation, progress feedback and cancellation in addition to the normal request lifecycle.","how":"Use FormData for multipart requests, track upload progress with a suitable HTTP API, validate file size/type, and allow cancellation where the UX requires it.","code":"const form = new FormData();\nform.append('file', file);\nawait fetch('/api/files', { method: 'POST', body: form });","delivery":"I treat file upload as a workflow with validation, progress, cancellation and backend validation rather than as a normal JSON POST.","followups":["How do you upload multiple files?", "Where should file type validation happen?"],"traps":["Client-side file validation is only a UX check; the server must validate too."]},
{"id":"react-096","level":"L3","title":"Frontend authorization versus backend authorization","subtopic":"Security","what":"Frontend authorization improves UX by hiding or disabling actions, but it cannot enforce security by itself.","how":"The backend remains the source of truth for authorization. React can use claims or permissions to decide what to render, while every protected API verifies authorization independently.","code":"{canDelete && <button onClick={deleteOrder}>Delete</button>}","delivery":"I use frontend authorization for user experience, but I never trust it as a security boundary. The Spring backend must enforce the permission on the API.","followups":["Where should roles be stored?", "How should the UI handle 403?"],"traps":["Never assume hiding a button protects an endpoint."]},
{"id":"react-097","level":"L3","title":"Frontend environment configuration","subtopic":"Deployment","what":"React builds often need environment-specific API URLs and feature settings without hardcoding production values into components.","how":"Use the build tool environment mechanism, validate required variables, and separate public configuration from secrets.","code":"const apiBase = import.meta.env.VITE_API_BASE_URL;","delivery":"I keep environment configuration outside components and remember that browser-exposed variables are not secrets.","followups":["Where do secrets belong?", "Build-time vs runtime configuration?"],"traps":["Never put private API keys or credentials into browser bundles."]},
{"id":"react-098","level":"L3","title":"Code splitting by route and feature","subtopic":"Performance","what":"Code splitting reduces the initial JavaScript payload by loading code when it is needed.","how":"Use dynamic imports and lazy route boundaries for large or infrequently visited features, while preloading critical paths when useful.","code":"const AdminPage = lazy(() => import('./AdminPage.jsx'));","delivery":"I split code around user journeys and large features, then measure whether the smaller initial bundle improves real performance.","followups":["What is preloading?", "How do Suspense boundaries affect UX?"],"traps":["Do not create hundreds of tiny chunks without measuring network overhead."]},
{"id":"react-099","level":"L3","title":"React application observability","subtopic":"Production","what":"Frontend observability connects user-visible failures and performance problems to actionable diagnostics.","how":"Capture structured errors, route context, request identifiers and performance signals while removing sensitive data. Correlate frontend errors with backend logs when possible.","code":"console.error({ event: 'checkout_failed', orderId });","delivery":"For production debugging I want enough context to reproduce the issue and correlate it with backend telemetry, without logging tokens or sensitive user data.","followups":["What should not be logged?", "How do request IDs help?"],"traps":["Do not log passwords, access tokens or unnecessary personal data."]},
{"id":"react-100","level":"L3","title":"Designing a production React feature end-to-end","subtopic":"Architecture","what":"A production React feature needs more than a component: it needs state ownership, API integration, accessibility, error handling, tests and performance considerations.","how":"Start with the user flow and API contract, define state ownership, build accessible components, isolate data fetching, handle loading/error/empty states, test important paths, and measure performance after release.","code":"Feature flow:\nUI → hook/API client → REST endpoint → response mapping → UI state\n+ tests + telemetry","delivery":"My approach is to design the feature as a vertical slice: user experience, state, API contract, failure handling, tests and production observability all fit together.","followups":["How would you structure a large React feature?", "How would you debug it in production?"],"traps":["Do not optimize or abstract before understanding the feature requirements."]}
];
